+
+            default:
+                validateFieldNotPresent(DIMENSIONS_FIELD, dimensions);
+                validateFieldNotPresent(SIMILARITY_FIELD, similarity);
+                validateFieldNotPresent(ELEMENT_TYPE_FIELD, elementType);
