+        }
+    }
+
+    private void validateFieldNotPresent(String field, Object fieldValue) {
+        if (fieldValue != null) {
+            throw new IllegalArgumentException("[" + field + "] is not allowed for task_type [" + taskType.name() + "]");
+        }
+    }
